package router

import (
	"net/http"

	"github.com/gin-gonic/gin"
	swaggerfiles "github.com/swaggo/files"
	ginswagger "github.com/swaggo/gin-swagger"

	"github.com/tahedig/too-good-to-go/backend/docs" // generated by `make swagger`
	"github.com/tahedig/too-good-to-go/backend/internal/bootstrap"
)

// swaggerCSP replaces the API's strict "default-src 'none'" policy on the
// Swagger routes only: the UI needs its own scripts, inline styles and data:
// images, and calls the API from the same origin.
const swaggerCSP = "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; " +
	"img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'"

// registerSwagger serves the UI at /swagger/index.html and the spec at
// /swagger/doc.json.
func registerSwagger(r *gin.Engine) {
	// Use the host the browser is on, so "Try it out" works behind any address.
	docs.SwaggerInfo.Host = ""

	r.GET(bootstrap.SwaggerPath, func(c *gin.Context) {
		c.Redirect(http.StatusMovedPermanently, bootstrap.SwaggerPath+"/index.html")
	})
	r.GET(bootstrap.SwaggerPath+"/*any",
		func(c *gin.Context) {
			c.Header("Content-Security-Policy", swaggerCSP)
			c.Next()
		},
		ginswagger.WrapHandler(swaggerfiles.Handler,
			ginswagger.PersistAuthorization(true), // keep the token across page reloads
			ginswagger.DocExpansion("list"),
		),
	)
}
